using Microsoft.AspNetCore.SignalR.Protocol;
using System.ComponentModel.DataAnnotations;

namespace StudentIncidentSystem.Models
{
    public class IncidentReport
    {
        public int Id { get; set; }

        // Example: INC-2026-000123 (generated by IncidentService in Stage 7)
        [Required, StringLength(30)]
        public string ReferenceNumber { get; set; } = string.Empty;

        [Required]
        public string ReporterId { get; set; } = string.Empty;
        public ApplicationUser? Reporter { get; set; }

        [Required]
        public int CategoryId { get; set; }
        public IncidentCategory? Category { get; set; }

        [Required, StringLength(150)]
        public string Title { get; set; } = string.Empty;

        [Required, StringLength(4000)]
        public string Description { get; set; } = string.Empty;

        // When the incident happened (date and time)
        public DateTime IncidentDateTime { get; set; }

        [Required, StringLength(200)]
        public string Location { get; set; } = string.Empty;

        [StringLength(1000)]
        public string? PeopleInvolved { get; set; }

        public IncidentStatus Status { get; set; } = IncidentStatus.Submitted;

        // Visible to the student once the case is resolved
        [StringLength(2000)]
        public string? ResolutionSummary { get; set; }

        public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow;
        public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow;
        public DateTime? ResolvedAtUtc { get; set; }
        public DateTime? ClosedAtUtc { get; set; }

        public ICollection<IncidentAttachment> Attachments { get; set; } = new List<IncidentAttachment>();
        public ICollection<CaseAssignment> Assignments { get; set; } = new List<CaseAssignment>();
        public ICollection<CaseMessage> Messages { get; set; } = new List<CaseMessage>();
        public ICollection<InvestigationNote> InvestigationNotes { get; set; } = new List<InvestigationNote>();
        public ICollection<IncidentStatusHistory> StatusHistory { get; set; } = new List<IncidentStatusHistory>();
    }
}